mapper.select:
select * from fin_bom_title left join fin_product on fin_bom_title.fin_product_id = fin_product.id where fin_bom_title.id in (

    select distinct fin_bom.bom_title_id from fin_bom where (productId,vault) in (select * from(
        select product.id,vault from product where concat(product.`name`,product.material_number)  LIKE CONCAT('%',#{str},'%') and deleteSign = 0
        union all
        select fin_product.id,vault from fin_product where concat(fin_product.fin_product_name,fin_product.fin_material_number)  LIKE CONCAT('%',#{str},'%') and deleteSign = 0
        ) as a)
        ) and fin_product.deleteSign = 0  limit #{begin},#{size}
